/*
* seq_status - CSR
* Auto-Negotiation and Link Training Sequencer Status Provides the following status bits: - Link Ready- Auto-Negotiation Timeout- Link Training Timeout- Sequencer mode for PCS reconfiguration- RS-FEC ability
* RO - Cold reset
*/

union nicia_csr_nni_an_lt_seq_status {
  struct {
      uint32_t seq_link_ready :1; /* Sequencer Link Ready 1: The auto-negotiation and link training sequencer thinks the link is ready for data mode 0: Link not ready  - 0 */
      uint32_t seq_an_timeout :1; /* Sequencer Auto-Negotiation Timeout 1: Auto-negotiation timeout occurred 0: No timeout occurred  - 0 */
      uint32_t seq_lt_timeout :1; /* Sequencer Link Training Timeout 1: Link fail timer expired while in Link Training mode 0: No timeout occurred  - 0 */
      uint32_t reserved0 :5;
      uint32_t seq_reconfig_mode :14; /* Sequencer Mode for PCS Reconfiguration 14'b00000000000001: AN mode 14'b00000000000010: LT mode 14'b00000000000100: 10G data mode 14'b00000000001000: 25G data mode 14'b00000000010000: 50G-R2 data mode 14'b00000000100000: 100G-R4 data mode 14'b00000001000000: 40G-R4 data mode 14'b00000010000000: 100G-R2 data mode 14'b00000100000000: 50G-R1 data mode 14'b00001000000000: 200G-R4 data mode 14'b00010000000000: 400G-R8 data mode 14'b00100000000000: 100G-R1 data mode 14'b01000000000000: 200G-R2 data mode 14'b10000000000000: 400G-R4 data mode All other settings reserved - The sequencer modifies the datapath as required to move through the stages of Auto-negotiation and Link training - This status register lets you know which step is in progress, and how the datapath is configured  - 0 */
      uint32_t reserved1 :9;
      uint32_t kr_paused :1; /* Indicates auto-negotiation and link training function is paused due to 0xB0[31] 1: AN/LT Function Paused 0: Normal auto-negotiation and link training function  - 0 */
  } __attribute__((packed)) fields;
  uint32_t csr;
};
